        if i > 0 and sorted_l[i] == sorted_l[i - 1]:
            continue

        left = i + 1
        right = n - 1

        while left < right:
            current_sum = sorted_l[i] + sorted_l[left] + sorted_l[right]
            if current_sum == 0:
                return True
            elif current_sum < 0:
                left += 1
            else:
                right -= 1

