    current_type = None  # 'space' or 'word'

    for char in s:
        if char == ' ':
            if current_type != 'space':
                # Transition from word to space
                if current_token:
                    tokens.append(current_token)
                    current_token = ''
                current_type = 'space'
            current_token += char
        else:
