def encode(message):
    """
    Encodes the message by swapping the case of all letters and replacing vowels with the letter two places ahead in the alphabet.

    Parameters:
    message (str): The input string to be encoded.

    Returns:
    str: The encoded message.
    """
    result = []
    vowels = {'a', 'e', 'i', 'o', 'u'}
    for c in message:
        if c.isalpha():
            swapped = c.swapcase()
            if swapped.lower() in vowels:
                new_char = chr(ord(swapped) + 2)
            else:
                new_char = swapped
        else:
            new_char = c
        result.append(new_char)
    return ''.join(result)

